    static String questionText(JSONObject q){StringBuilder s=new StringBuilder(q.optString("stem"));JSONObject opts=q.optJSONObject("options");if(opts!=null){List<String> keys=new ArrayList<>();Iterator<String> it=opts.keys();while(it.hasNext())keys.add(it.next());Collections.sort(keys);for(String k:keys)s.append("\n").append(k).append(". ").append(opts.optString(k));}return s.toString();}
