    void wordReview(String raw){
        final JSONArray words;try{words=AiClient.words(raw);}catch(Exception invalid){page("单词补全未完成","返回内容不完整或格式有误，没有保存为单词。原结果与输入已保留，可以返回后手动重试。",this::wordAI);a.button("查看原始响应",()->new AlertDialog.Builder(a).setTitle("原始响应").setMessage(raw).setPositiveButton("关闭",null).show());a.primary("返回重新补全",this::wordAI);return;}
        page("核对单词补全","共 "+words.length()+" 个单词；可修改各项内容，确认后保存。",this::wordAI);
        for(int i=0;i<words.length();i++){JSONObject w=words.optJSONObject(i);a.ui.section("单词 "+(i+1),"");String[] keys={"word","meaning","phonetic","example"},labels={"单词","中文释义","音标","例句与译文"};int[] limits={300,2000,300,4000};for(int k=0;k<keys.length;k++){String key=keys[k];EditText e=field(labels[k],w.optString(key),k==1||k==3);e.setFilters(new InputFilter[]{new InputFilter.LengthFilter(limits[k])});watch(e,()->safe(()->{w.put(key,e.getText().toString());a.book.putState("word_ai_result",new JSONObject().put("words",words).toString());}));}}
        a.primary("核对并保存",()->safe(()->{JSONArray checked=AiClient.words(new JSONObject().put("words",words).toString());a.book.db.beginTransaction();try{for(int i=0;i<checked.length();i++){JSONObject w=checked.getJSONObject(i);a.book.word(null,w.getString("word"),w.getString("meaning"),w.getString("phonetic"),w.getString("example"));}a.book.putState("word_ai_result","");a.book.db.setTransactionSuccessful();}finally{a.book.db.endTransaction();}wordList();a.status("已保存 "+checked.length()+" 个单词。");}));a.button("返回单词本",this::wordList);
    }
