    int importLocal(Notebook target) throws Exception {
        Notebook source=new Notebook(new File(new File(a.getFilesDir(),"local"),"LOCAL"),"LOCAL");try{return importLocal(target,source);}finally{source.close();}
    }
    static int importLocal(Notebook target,Notebook source) throws Exception {
        if(!source.uid.equals("LOCAL")||target.uid.equals("LOCAL"))throw new IOException("请选择账号题库接收本机题目。");
            File folder=new File(target.root,"backups");folder.mkdirs();try(OutputStream out=new FileOutputStream(new File(folder,"before-import-"+CloudApi.id()+".zip"))){NotebookBackup.export(target,out);}int count=0;
            target.db.beginTransaction();try{for(JSONObject row:source.entries("","","")){String sid=row.getString("id");try(android.database.Cursor c=target.db.rawQuery("SELECT 1 FROM imports WHERE source_id=?",new String[]{sid})){if(c.moveToFirst())continue;}
                String id=CloudApi.id();JSONObject p=row.getJSONObject("payload");JSONArray images=new JSONArray(),originals=p.getJSONArray("attachments");for(int i=0;i<originals.length();i++){JSONObject image=originals.getJSONObject(i);String key=image.getString("key"),ext=key.substring(key.lastIndexOf('.')+1);images.put(target.addImage(CloudApi.read(source.file(image),CloudApi.MAX_IMAGE),ext,image.getString("original_name"),id));}target.save(id,p.getJSONObject("question"),images);JSONObject local=target.entry(id);local.getJSONObject("payload").put("review",p.get("review"));target.mutate(id,local.getJSONObject("payload"),false);target.db.execSQL("INSERT INTO imports VALUES(?,?)",new Object[]{sid,id});count++;}target.db.setTransactionSuccessful();}finally{target.db.endTransaction();}return count;
    }
