    void exportJson() throws Exception {JSONArray questions=new JSONArray();for(JSONObject e:libraryRows())questions.put(e.getJSONObject("payload").getJSONObject("question"));String json=new JSONObject().put("questions",questions).toString();if(json.getBytes(StandardCharsets.UTF_8).length>8*1024*1024)throw new IOException("JSON 文本超过 8 MB，请缩小导出范围。");a.book.putState("json_export",json);choose(JSON_SAVE,"application/json",true);}
